import functools

# 使用记忆化优化，避免朴素递归导致的指数级重复计算
# 保持原始函数接口：fibonacci(n: int) -> int
# noise_seed=4554
@functools.lru_cache(maxsize=None)
def fibonacci(n: int) -> int:
    if n <= 0:
        return 0
    if n == 1:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

